import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "base", label: "Icon base path", value: "/icons" })}${field({ id: "name", label: "App name", value: "jquery.app" })}${field({ id: "theme", label: "Theme color", value: "#0f766e" })}${field({ id: "bg", label: "Background color", value: "#ffffff" })}</div>`,generate(root) {const base = root.querySelector("#base").value.replace(/\/$/, "");const name = root.querySelector("#name").value.trim();const theme = root.querySelector("#theme").value.trim();const bg = root.querySelector("#bg").value.trim();const output = [`<link rel="icon" href="${attrEscape(base)}/favicon.ico" sizes="any">`,`<link rel="icon" href="${attrEscape(base)}/icon.svg" type="image/svg+xml">`,`<link rel="apple-touch-icon" href="${attrEscape(base)}/apple-touch-icon.png">`,`<link rel="manifest" href="${attrEscape(base)}/site.webmanifest">`,`<meta name="theme-color" content="${attrEscape(theme)}">`,"","site.webmanifest:",JSON.stringify({name,short_name: name,icons: [{ src: `${base}/icon-192.png`, sizes: "192x192", type: "image/png" },{ src: `${base}/icon-512.png`, sizes: "512x512", type: "image/png" }],theme_color: theme,background_color: bg,display: "standalone"}, null, 2)].join("\n");return { output };}};